const arabicDigits=value=>String(value).replace(/[0-9]/g,d=>"٠١٢٣٤٥٦٧٨٩"[Number(d)]);
const safeNum=v=>{const n=Number(v);return Number.isFinite(n)?n:0};
const fmtScore=s=>{const w=Math.floor(s);return arabicDigits(w)+(s%1>=0.5?" ونص":"")};
// Round 3.2.2 P1-5: binding 25-second movement breaks (one per run,
// rotating) — the done button stays disabled until the timer elapses.
const MOVE_BREAKS=["نطّ ٥ مرات زي الأرنب","امشي زي الأسد ١٠ خطوات","ارفع إيديك لفوق ونزّلهم ٥ مرات"];
const MOVE_EMOJIS=["🐰","🦁","🙌"];
// Round 3.2.2 P1-5: BINDING movement break — a 25s countdown, and the
// "done" button stays disabled until the timer elapses, so the break
// actually discharges energy instead of being skippable in one tap.
// Shared by the main quiz and every other activity that shows a break
// (letter quiz, math journeys, memory game, science, chess).
// show(host, onDone) renders the break into host, speaks the instruction,
// and calls onDone only after the child taps the enabled button.
// cancel(host) stops a running timer (screen torn down mid-break).
const MOVE_BREAK_SECONDS=25;
const __moveArabic=n=>String(n).replace(/[0-9]/g,d=>"٠١٢٣٤٥٦٧٨٩"[Number(d)]);
function __moveBreakShow(host,onDone){
  const mi=(window.__moveCount=(window.__moveCount||0))%MOVE_BREAKS.length;window.__moveCount++;
  const text=MOVE_BREAKS[mi];
  host.innerHTML='<div class="move-break-emoji">'+MOVE_EMOJIS[mi]+'</div><p><strong>وقت الحركة يا بطل! 🏃</strong><br>'+text+'</p><p class="move-break-count">⏳ لسه '+__moveArabic(MOVE_BREAK_SECONDS)+' ثانية… اتحرك يا بطل!</p><button type="button" class="primary move-done-btn" disabled>⏳ استنى '+__moveArabic(MOVE_BREAK_SECONDS)+' ثانية…</button>';
  const btn=host.querySelector(".move-done-btn"),countEl=host.querySelector(".move-break-count");
  try{window.MatthewVoice?.speak(text,"ar-EG")}catch(_){}
  let left=MOVE_BREAK_SECONDS;
  const timer=setInterval(()=>{
    if(!document.contains(host)){clearInterval(timer);return}
    left--;
    if(left>0){if(countEl)countEl.textContent="⏳ لسه "+__moveArabic(left)+" ثانية… اتحرك يا بطل!";if(btn)btn.textContent="⏳ استنى "+__moveArabic(left)+" ثانية…";return}
    clearInterval(timer);host.__moveTimer=null;
    if(countEl)countEl.textContent="برافو يا بطل! خلصت وقت الحركة 🎉";
    if(btn){btn.disabled=false;btn.textContent="✅ خلصت، كمّل يا بطل"}
  },1000);
  host.__moveTimer=timer;
  if(btn)btn.addEventListener("click",()=>{if(btn.disabled)return;clearInterval(timer);host.__moveTimer=null;if(typeof onDone==="function")onDone()});
}
function __moveBreakCancel(host){if(host&&host.__moveTimer){clearInterval(host.__moveTimer);host.__moveTimer=null}}
if(typeof window!=="undefined"){window.MatthewMoveBreak={seconds:MOVE_BREAK_SECONDS,texts:MOVE_BREAKS,emojis:MOVE_EMOJIS,show:__moveBreakShow,cancel:__moveBreakCancel};}
// Round 3.2.2 P2: quiz resume — the saved progress is finally READ.
// saveQuizProgress stores the picked question set too: a fresh start()
// re-picks 10 random questions, so an index alone would point at a
// different question. Progress is keyed per category, so leaving one quiz
// for another never wipes the first. Re-entering the SAME quiz resumes
// automatically at the unanswered question with the saved score — no
// button, so a child can never be stranded on a dead control. finish()
// clears the slot so a completed quiz never resurrects.
function saveQuizProgress(){try{if(questions&&questions.length&&index<questions.length)localStorage.setItem("matthewQuizProgress:"+category,JSON.stringify({category,questions,index,score,at:Date.now()}))}catch(_){}}
function loadQuizProgress(cat){try{const raw=localStorage.getItem("matthewQuizProgress:"+cat);if(!raw)return null;const p=JSON.parse(raw);if(!p||typeof p!=="object"||p.category!==cat)return null;if(!Array.isArray(p.questions)||!p.questions.length)return null;for(const q of p.questions){if(!q||typeof q.q!=="string"||!Array.isArray(q.a)||q.a.length!==4||!Number.isInteger(q.c)||q.c<0||q.c>=q.a.length)return null}const idx=Math.floor(Number(p.index));if(!Number.isFinite(idx)||idx<0||idx>=p.questions.length)return null;const sc=Number(p.score);if(!Number.isFinite(sc)||sc<0||sc>idx)return null;return{category:p.category,questions:p.questions,index:idx,score:sc}}catch(_){return null}}
function clearQuizProgress(cat){try{localStorage.removeItem("matthewQuizProgress:"+(cat||category))}catch(_){}}
const $=id=>document.getElementById(id);let category="mixed",questions=[],index=0,score=0,answered=false,installEvent=null,lastChoices=[];
// Round 3.2.1 note 25b (Miss Nancy draft): quiz intros — spoken before the
// FIRST question of a run only, so later questions are never delayed.
const NANCY_QUIZ_INTROS=[
  "يلا يا ملك ماثيو! اسمع السؤال كويس واختار الإجابة الصح، أنا واثقة فيك يا بطل!",
  "اختبار جديد يا بطلي ماثيو! ركّز معايا وجاوب، وكل إجابة صح ليها نجمة!"
];
let quizIntroIndex=0;
