window.answerPic=function(text,q){return window.AnswerPics[text]||(q&&q.e)||"⭐"};
// حارس صور الأسئلة (تدقيق الصور، الجولة ٣.٢.١): الطفل اللي لسه ما بيعرفش
// يقرأ بيقرأ الصورة مش الكلام، فصورة السؤال لازم ما تكشفش الإجابة الصح
// ولا ترسم اختيار غلط — ولو حصل، نعرض 🤔 بدلها. الخريطة PIC_MEANS بتقول
// كل إيموجي بيرسم إيه (لون البرتقالة في الثعلب، أجنحة الفراشة...).
const PIC_MEANS={"🌞":["الشمس"],"🌙":["القمر","قمر"],"🦊":["الثعلب","ثعلب","برتقالي"],"🐯":["النمر","نمر"],"🦋":["الفراشة","فراشة","جناحيها","الأجنحة"],"🌿":["الورقة","ورقة","العشب","أخضر"],"🌦":["بعد المطر","المطر"],"🏃":["نزقها برجلينا"],"🏖":["هتطفو فوق المية","هتطفو فوق","الماء","البحر"],"🌌":["بالليل","الليل","النجوم"],"❄":["بطريق","الثلج"],"🍌":["الموز","موز","أصفر"],"🍅":["الطماطم","طماطم","أحمر"],"🌱":["أخضر","العشب"],"🩺":["القلب"],"🟪":["مربع"],"🔺":["مثلث"]};
function questionEmojiSafe(q){if(!q||!q.e)return "🤔";if(/شكل|ضلع/.test(q.q||""))return "🤔";const strip=s=>String(s).replace(/\uFE0F/g,"");const shown=q.e;const clean=strip(shown);const depicts=word=>{if(!word)return false;if(String(word).length<=1)return false;/* single-letter answers: their AnswerPics entry is the mnemonic word-picture of the letter (ت→🍎), not a depiction of the glyph — it cannot reveal which letter is first. */if(window.AnswerPics&&strip(window.AnswerPics[word])===clean)return true;for(const key of Object.keys(PIC_MEANS)){if(clean.includes(strip(key))&&PIC_MEANS[key].includes(word))return true}return false};if(!q.a)return shown;for(let i=0;i<q.a.length;i++)if(depicts(q.a[i]))return "🤔";return shown}
window.questionEmojiSafe=questionEmojiSafe;
function pickQuestions(source,cat){const mastery=window.MatthewMastery;if(!mastery||!mastery.weight)return shuffle(source).slice(0,10);const scored=source.map(q=>{const skill=(cat==="mixed"?"mixed":cat)+":"+q.q;return{q,key:Math.pow(Math.random(),1/Math.max(0.25,mastery.weight(skill)))}});scored.sort((a,b)=>b.key-a.key);const picked=scored.slice(0,10).map(x=>x.q);return picked.length?picked:shuffle(source).slice(0,10)}
function start(cat){category=cat;const saved=loadQuizProgress(cat);if(saved){questions=saved.questions;index=saved.index;score=saved.score}else{const source=cat==="mixed"?Object.values(bank).flat():bank[cat];questions=pickQuestions(source,cat);index=0;score=0}$("gameList").classList.add("hidden");$("learningList")?.classList.add("hidden");$("result").classList.add("hidden");$("quiz").classList.remove("hidden");$("categoryName").textContent=names[cat];showQuestion();window.scrollTo({top:0,behavior:"smooth"})}
