function finish(){ clearQuizProgress(category);$("quiz").classList.add("hidden");$("result").classList.remove("hidden");const stars=Math.max(1,Math.round(score/questions.length*5));$("resultText").textContent="جاوبت صح على "+fmtScore(score)+" من "+arabicDigits(questions.length)+" أسئلة";$("resultStars").textContent="⭐".repeat(stars)+"☆".repeat(5-stars);const old=safeNum(localStorage.getItem("matthewBest")),total=safeNum(localStorage.getItem("matthewStars")),points=safeNum(localStorage.getItem("matthewPoints")),trophies=safeNum(localStorage.getItem("matthewTrophies"));localStorage.setItem("matthewBest",Math.max(old,score));localStorage.setItem("matthewStars",total+stars);localStorage.setItem("matthewPoints",points+score*10);if(score===questions.length||(old>0&&score>old))localStorage.setItem("matthewTrophies",trophies+1);let history=[];try{history=JSON.parse(localStorage.getItem("matthewHistory")||"[]");if(!Array.isArray(history))history=[]}catch(_){history=[]}history.unshift({category:names[category],score,total:questions.length,stars,points:score*10,at:Date.now()});localStorage.setItem("matthewHistory",JSON.stringify(history.slice(0,30)));const resultLine="جاوبت صح على "+fmtScore(score)+" من "+arabicDigits(questions.length)+" أسئلة";const resultTip=score>=Math.ceil(questions.length*0.7)?"برافو يا ملك ماثيو! انت بطل شاطر أوي!":"محاولة جميلة يا بطل ماثيو! العب تاني وهتجيب نجوم أكتر!";try{if(window.MatthewVoice?.speakSequence)window.MatthewVoice.speakSequence([resultLine,resultTip],"ar-EG");else window.MatthewVoice?.speak(resultLine,"ar-EG")}catch(_){}updateStats();window.scrollTo({top:0,behavior:"smooth"})}
function updateStats(){$("totalStars").textContent=arabicDigits(safeNum(localStorage.getItem("matthewStars")));$("totalPoints").textContent=arabicDigits(safeNum(localStorage.getItem("matthewPoints")));$("totalTrophies").textContent=arabicDigits(safeNum(localStorage.getItem("matthewTrophies")));$("bestScore").textContent=arabicDigits(safeNum(localStorage.getItem("matthewBest")));let ar=0,en=0;try{ar=Number(JSON.parse(localStorage.getItem("matthewMathProgress")||"{}").completed)||0}catch(_){}try{en=Number(JSON.parse(localStorage.getItem("matthewEnglishMathProgress")||"{}").completed)||0}catch(_){}const aml=$("arabicMathLevel");if(aml)aml.textContent=arabicDigits(Math.min(20,ar+1));const eml=$("englishMathLevel");if(eml)eml.textContent=arabicDigits(Math.min(20,en+1))}
$("gameList").addEventListener("click",e=>{const card=e.target.closest("[data-category]");if(card)start(card.dataset.category)});$("nextBtn").addEventListener("click",()=>{if(index<questions.length-1){index++;showQuestion()}else finish()});$("replayBtn").addEventListener("click",()=>{window.__askNow?.()});$("backBtn").addEventListener("click",()=>{$("quiz").classList.add("hidden");$("gameList").classList.remove("hidden");saveQuizProgress();window.__qToken=(window.__qToken||0)+1;try{window.MatthewVoice?.stop()}catch(_){}const mb=$("moveBreak");if(mb)mb.remove();const aEl=$("answers");if(aEl)aEl.style.visibility=""});$("homeBtn").addEventListener("click",()=>{window.__qToken=(window.__qToken||0)+1;try{window.MatthewVoice?.stop()}catch(_){}$("result").classList.add("hidden");$("gameList").classList.remove("hidden");$("learningList")?.classList.remove("hidden")});$("againBtn").addEventListener("click",()=>start(category));updateStats();
window.addEventListener("beforeinstallprompt",e=>{e.preventDefault();installEvent=e;$("installBtn").classList.remove("hidden")});$("installBtn").addEventListener("click",async()=>{if(!installEvent)return;installEvent.prompt();await installEvent.userChoice;installEvent=null;$("installBtn").classList.add("hidden")});if("serviceWorker"in navigator)window.addEventListener("load",()=>navigator.serviceWorker.register("./sw.js").catch(()=>{}));
// ===== Home doors: four big sections instead of one long overwhelming list =====
(function initHomeDoors() {
  const main = document.querySelector("main");
  const learnList = document.getElementById("learningList");
  const gameList = document.getElementById("gameList");
  if (!main || !learnList || !gameList) return;
  const hero = document.querySelector(".hero");
  const heads = [...document.querySelectorAll(".section-head")];
  const DOORS = [
    { id: "learn", icon: "📚", label: "الدروس", hint: "الشرح خطوة خطوة" },
    { id: "quiz", icon: "🏆", label: "الأسئلة والاختبارات", hint: "اختبر شطارتك" },
    { id: "games", icon: "🎮", label: "الألعاب", hint: "قصص وألعاب ممتعة" },
    { id: "colors", icon: "🎨", label: "الألوان والتلوين", hint: "ارسم ولوّن الحروف" }
  ];
  const nav = document.createElement("nav");
  nav.id = "homeDoors"; nav.className = "home-doors"; nav.setAttribute("aria-label", "أقسام المملكة");
  nav.innerHTML = DOORS.map(d => '<button type="button" class="door door-' + d.id + '" data-door="' + d.id + '"><span class="door-icon" aria-hidden="true">' + d.icon + '</span><strong>' + d.label + '</strong><small>' + d.hint + '</small></button>').join("");
  const bar = document.createElement("div");
  bar.id = "doorBar"; bar.className = "door-bar"; bar.style.display = "none";
  // Round 3.2.2 P1-8: one unified 🏠 button, same place everywhere, shown
  // whenever any activity panel is open; Android back goes home first.
  const fab = document.createElement("button");
  fab.id = "homeFab"; fab.type = "button"; fab.className = "home-fab"; fab.style.display = "none";
  fab.textContent = "🏠"; fab.setAttribute("aria-label", "العودة للمملكة");
  main.appendChild(fab);
  const goHome = () => { window.__qToken = (window.__qToken || 0) + 1; try { window.MatthewVoice?.stop(); } catch (_) {} saveQuizProgress(); document.querySelectorAll("main > section.quiz-panel, main > section.academy-panel, main > section.result-panel").forEach(x => { if (!x.classList.contains("hidden")) x.classList.add("hidden"); }); current = null; apply(); window.scrollTo({ top: 0, behavior: "smooth" }); };
  fab.addEventListener("click", goHome);
  const updateHomeFab = open => { fab.style.display = open ? "" : "none"; };
  document.addEventListener("backbutton", () => { if (activityOpen()) goHome(); else if (current) { current = null; apply(); } else { try { window.Capacitor?.Plugins?.App?.exitApp?.(); } catch (_) {} } }, false);
  bar.innerHTML = '<button type="button" id="doorBack" class="back">→ كل الأقسام</button><strong id="doorTitle"></strong>';
  const anchor = heads[0] || learnList;
  main.insertBefore(nav, anchor);
  main.insertBefore(bar, anchor);
  const parentCorner = document.createElement("div");
  parentCorner.id = "parentCorner";
  gameList.after(parentCorner);
  let current = null;
  const classify = card => {
    if (card.dataset && card.dataset.stories) return "games";
    if (card.dataset && card.dataset.braveStories) return "games";
    if (card.dataset && card.dataset.workshop) return "games"; // Round 3.2: colouring-games workshop lives in the Games door
    if (card.dataset && card.dataset.memory) return "games"; // Round 3.2.1: memory game lives in the Games door
    if (card.dataset && card.dataset.chess) return "games"; // Round 3.2.2 P0-1: chess card lives in the Games door
    const t = card.textContent || "";
    if (t.includes("لوحة ولي الأمر")) return "parent";
    if (t.includes("اكتب بإصبعك")) return "colors";
    if (t.includes("التوصيل واسمع")) return "games";
    if (card.closest("#gameList")) return card.dataset.category ? "quiz" : "games";
    return "learn";
  };
  // Round 3.2.2 P0-2: the activity signal MUST be the panels, not the lists.
  // apply() now owns the lists' hidden class (it adds it on home too), so
  // reading it back as "an activity is open" conflated home with activity
  // and opening a door from home left the lists invisible. Every activity
  // panel carries quiz-panel / academy-panel / result-panel, so a visible
  // panel is the honest signal.
  const activityOpen = () => [...document.querySelectorAll("main > section.quiz-panel, main > section.academy-panel, main > section.result-panel")].some(s => !s.classList.contains("hidden"));
  function apply() {
    [...learnList.children, ...gameList.children].forEach(c => {
      if (classify(c) === "parent" && c.parentElement !== parentCorner) parentCorner.append(c);
    });
    const open = activityOpen();
    if (hero) hero.style.display = (!open && !current) ? "" : "none";
    nav.style.display = (!open && !current) ? "" : "none";
    bar.style.display = (!open && current) ? "" : "none";
    heads.forEach(h => { h.style.display = "none"; });
    parentCorner.style.display = (!open && !current) ? "" : "none";
    // Round 3.2.2 P0 freeze fix: in Chromium a no-op classList.add/remove
    // on an observed element STILL fires a MutationObserver record, and the
    // observer below calls apply() — so an unguarded write here looped
    // forever and the page never loaded. Only write the class when the
    // value actually changes (toggle() already no-ops silently, but the
    // explicit contains-guarded add/remove below states the rule plainly).
    [learnList, gameList].forEach(list => {
      if (open || !current) { list.style.display = "none"; if (!list.classList.contains("hidden")) list.classList.add("hidden"); return; }
      let any = false;
      [...list.children].forEach(c => { const show = classify(c) === current; c.style.display = show ? "" : "none"; if (show) any = true; });
      list.style.display = any ? "" : "none";
      if (any) { if (list.classList.contains("hidden")) list.classList.remove("hidden"); }
      else if (!list.classList.contains("hidden")) list.classList.add("hidden");
    });
    updateHomeFab(open);
  }
  nav.querySelectorAll("[data-door]").forEach(b => b.addEventListener("click", () => {
    current = b.dataset.door;
    const d = DOORS.find(x => x.id === current);
    bar.querySelector("#doorTitle").textContent = d.icon + " " + d.label;
    apply();
    window.scrollTo({ top: 0, behavior: "smooth" });
  }));
  bar.querySelector("#doorBack").addEventListener("click", () => { current = null; apply(); window.scrollTo({ top: 0, behavior: "smooth" }); });
  const obs = new MutationObserver(() => apply());
  [learnList, gameList].forEach(l => obs.observe(l, { childList: true, attributes: true, attributeFilter: ["class"] }));
  document.querySelectorAll("main > section").forEach(s => obs.observe(s, { attributes: true, attributeFilter: ["class"] }));
  window.addEventListener("load", () => setTimeout(apply, 60));
  setTimeout(apply, 1200);
  main.addEventListener("click", () => setTimeout(apply, 0), true);
  // Round 3.2.1 note 25b: مس نانسي greets Matthew on the home screen
  // (rotating). Spoken by text so it resolves to the recorded clip once
  // generated; the hero-hidden check skips it when a door is already open.
  const NANCY_GREETS = [
    "أهلاً يا ملك ماثيو! أنا مس نانسي، وبحبك أوي! يلا نلعب ونتعلم مع بعض!",
    "أنا مس نانسي وبحبك يا ماثيو! وحشتني أوي، يلا نبدأ يوم جميل مع بعض!",
    "أهلاً يا بطلي ماثيو! أنا مس نانسي، أنا فخورة بيك أوي! يلا نشوف هنلعب إيه النهارده!"
  ];
  try {
    const gi = Number(localStorage.getItem("matthewGreetIdx") || 0) || 0;
    localStorage.setItem("matthewGreetIdx", String((gi + 1) % NANCY_GREETS.length));
    setTimeout(() => { const hero = document.querySelector(".hero"); if (!hero || hero.style.display === "none") return; window.MatthewVoice?.speak(NANCY_GREETS[gi % NANCY_GREETS.length], "ar-EG"); }, 700);
  } catch (_) {}
  apply();
})();
